contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public payable {
        require(true);

        // Set up arbitrary state via the public entry point. This call always reverts for the
        // non-depositor test contract, so wrap it in try/catch and continue so version() is reached.
        bool setReverted;
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
            setReverted = false;
        } catch {
            setReverted = true;
        }

        // The deciding call: version() must complete and return a deterministic, non-empty string.
        string memory v1 = c.version();
        string memory v2 = c.version();
        bytes memory b1 = bytes(v1);
        bytes memory b2 = bytes(v2);
        assert(b1.length > 0 && b1.length == b2.length && keccak256(b1) == keccak256(b2));
    }

    receive() external payable {}
}

